// 验证输入参数
const { query, platforms, userId } = $json.body;

if (!query || !platforms || platforms.length === 0) {
  throw new Error('缺少必要参数: query 和 platforms');
}

$items[0].json.processedInput = {
  query: query.trim(),
  platforms: platforms,
  userId: userId || 'anonymous',
  timestamp: new Date().toISOString()
};

return $items;

// 处理AI生成结果
const aiResponse = $json.choices[0].message.content;
// 从“输入验证”节点获取平台信息
const platforms = $('输入验证').item.json.processedInput.platforms;

// 解析AI响应并按平台分类
const results = {};
platforms.forEach(platform => {
  switch(platform) {
    case 'deep':
      results.deep = extractContent(aiResponse, ['深度', '报道', '角度']);
      break;
    case 'video':
      results.video = extractContent(aiResponse, ['视频', '脚本', '镜头']);
      break;
    case 'social':
      results.social = extractContent(aiResponse, ['社交', '文案', '#']);
      break;
    case 'radio':
      results.radio = extractContent(aiResponse, ['广播', '稿件', '播音']);
      break;
  }
});

// 通用的内容提取函数
function extractContent(text, keywords) {
  const lines = text.split('\n').filter(line => 
    keywords.some(keyword => line.includes(keyword))
  );
  // 如果找不到特定关键词的内容，则返回一个通用提示，而不是硬编码的示例
  return lines.length > 0 ? lines : [`未能在AI响应中找到关于[${keywords.join('/')}]的明确内容。`];
}

// 返回最终结果
return {
  executionId: $execution.id,
  status: 'completed',
  results: results,
  timestamp: new Date().toISOString()
};
